// starlight-llms-txt ships TypeScript, which Node will not strip inside node_modules, so Astro
// loads astro.config.mjs through its fallback Vite server. That server hard-codes
// `resolve.tsconfigPaths: true` (our `vite` option does not reach it) and walks up to the repo
// root tsconfig.json, which extends `.svelte-kit/tsconfig.json` — generated by `svelte-kit sync`
// and absent in a clean checkout (CI, Cloudflare Pages). Write an empty one when it is missing;
// an existing generated file is never touched.
import { existsSync, mkdirSync, writeFileSync } from 'node:fs';
const dir = new URL('../../.svelte-kit/', import.meta.url);
const file = new URL('tsconfig.json', dir);
if (!existsSync(file)) {
  mkdirSync(dir, { recursive: true });
  writeFileSync(file, '{}\n');
}
